resource "google_container_cluster" "primary" {
  name               = var.cluster_name
  location           = var.region
  project            = var.project_id
  node_pool {
    name               = "default-pool"
    node_count         = var.node_count
    vm_size            = var.node_size
    preemptible       = var.preemptible
    max_pods_per_node  = var.max_pods_per_node
