resource "azurerm_virtual_network" "azure_vnet" {
  name                = "azure-vnet"
  resource_group_name = var.azure_resource_group_name
  location            = var.azure_location
  address_space       = [var.azure_vnet_cidr]
}

# Create subnets on Azure
